// Base64-encoded hero images, inlined directly in the JS bundle.
// This bypasses Next.js/Turbopack static file serving entirely (public/hero/*.png),
// which was unreliable on this machine. A data URI never touches the network or the
// dev server''s static file pipeline at all -- the browser decodes it directly from
// the JS string.

export const phoneImage = "data:image/webp;base64,";

